create table RB_ACCT_WITHDRAW_TYPE (WITHDRAW_KEY VARCHAR(30) not null  ,CHANNEL VARCHAR(10) null  ,WITHDRAWAL_TYPE VARCHAR(1) not null  ,CLIENT_NO VARCHAR(22) not null  ,DAC_VALUE VARCHAR(200) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(WITHDRAW_KEY,WITHDRAWAL_TYPE,CLIENT_NO));